Lemma sb_epi : forall (mA m1 : mem) (t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word),
  bfacts mA -> munch (W_1s (B + -192)) mA m1 -> wmono asegs mA m1 -> mem_inv asegs m1 -> stk asegs m1 lo (B + -192) -> smid_facts m1 ->
  evt asegs smid (MS (mkR (Z_to_bv 64 comballoc_retS) (Z_to_bv 64 (B + -192)) gp (Z_to_bv 64 tpA) t0 t1 t2 (Z_to_bv 64 8) (Z_to_bv 64 n)
                        (Z_to_bv 64 (P + 4096)) a1 a2 a3 a4 a5 a6 a7 (Z_to_bv 64 8) (Z_to_bv 64 SZ) (Z_to_bv 64 (rz_size n))
                        (Z_to_bv 64 n) (Z_to_bv 64 INST) (Z_to_bv 64 (B + 40)) (Z_to_bv 64 (0 + - (8))) (Z_to_bv 64 7) (Z_to_bv 64 T)
                        (Z_to_bv 64 1) t3 t4 t5 t6)
